-- PRIVATE CANDIDATE58 / NOT CERTIFIED: requires exact-SQL full31 in both profiles.
-- Derived ONLY from preserved local draft and local catalog proofs; no ROOT access.
-- The pre-DDL plan uses ORIGINAL metadata and only cotacao.prosrc substitution.
-- Helper OID is allocated by PostgreSQL: evaluate saved plan after helper CREATE,
-- before cotacao CREATE OR REPLACE; do NOT silently adopt/reseal old catalogs.
BEGIN;
SET LOCAL search_path=pg_catalog,pg_temp;
SET LOCAL lock_timeout='10s';
SELECT pg_advisory_xact_lock(20261126,58),pg_advisory_xact_lock(20261126,51);
DO $pre58$ DECLARE roles58 jsonb;configs58 jsonb;settings58 jsonb;e jsonb;vproc pg_proc%ROWTYPE;actual jsonb; BEGIN
 IF current_user<>'postgres' OR session_user<>'postgres' OR current_setting('server_version_num')::int/10000<>17 OR current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION '58 PG17 owner/session/isolation required' USING ERRCODE='55000';END IF;
 SELECT jsonb_object_agg(rolname,jsonb_build_array(rolsuper,rolbypassrls,rolcanlogin)) INTO roles58 FROM pg_roles WHERE rolname IN('postgres','service_role','anon','authenticated');
 IF roles58 IS NULL OR roles58 NOT IN ('{"anon":[false,false,false],"authenticated":[false,false,false],"postgres":[false,false,true],"service_role":[false,false,false]}'::jsonb,'{"anon":[false,false,false],"authenticated":[false,false,false],"postgres":[false,true,true],"service_role":[false,true,false]}'::jsonb) THEN RAISE EXCEPTION '58 install role profile mismatch' USING ERRCODE='55000';END IF;
 -- Explicit reviewed whole profiles; select by the SAME original role flags, never by captured configs.
 -- Preserve literal strings, array order and NULL; do not normalize, merge, or adopt prior drift.
 SELECT jsonb_object_agg(rolname,to_jsonb(rolconfig)) INTO configs58 FROM pg_roles WHERE rolname IN('postgres','service_role','anon','authenticated');
 SELECT coalesce(jsonb_agg(jsonb_build_object('database_name',CASE WHEN s.setdatabase=0 THEN '*' ELSE d.datname END,'role_name',CASE WHEN s.setrole=0 THEN '*' ELSE r.rolname END,'setconfig',to_jsonb(s.setconfig)) ORDER BY CASE WHEN s.setdatabase=0 THEN '*' ELSE d.datname END,CASE WHEN s.setrole=0 THEN '*' ELSE r.rolname END),'[]'::jsonb) INTO settings58
 FROM pg_db_role_setting s LEFT JOIN pg_database d ON d.oid=s.setdatabase LEFT JOIN pg_roles r ON r.oid=s.setrole
 WHERE r.rolname IN('postgres','service_role','anon','authenticated') OR (s.setrole=0 AND (s.setdatabase=0 OR s.setdatabase=(SELECT oid FROM pg_database WHERE datname=current_database())));
 IF roles58='{"anon":[false,false,false],"authenticated":[false,false,false],"postgres":[false,false,true],"service_role":[false,false,false]}'::jsonb THEN
  IF configs58 IS DISTINCT FROM '{"anon":null,"authenticated":null,"postgres":null,"service_role":null}'::jsonb OR settings58 IS DISTINCT FROM '[]'::jsonb THEN RAISE EXCEPTION '58 install roleconfig profile mismatch' USING ERRCODE='55000';END IF;
 ELSE
  IF current_database()<>'postgres' OR configs58 IS DISTINCT FROM '{"anon":["statement_timeout=3s"],"authenticated":["statement_timeout=8s"],"postgres":["search_path=\"\\$user\", public, extensions"],"service_role":null}'::jsonb OR settings58 IS DISTINCT FROM '[{"database_name":"*","role_name":"anon","setconfig":["statement_timeout=3s"]},{"database_name":"*","role_name":"authenticated","setconfig":["statement_timeout=8s"]},{"database_name":"*","role_name":"postgres","setconfig":["search_path=\"\\$user\", public, extensions"]},{"database_name":"postgres","role_name":"*","setconfig":["app.settings.jwt_exp=3600"]}]'::jsonb THEN RAISE EXCEPTION '58 install roleconfig profile mismatch' USING ERRCODE='55000';END IF;
 END IF;
 IF (SELECT count(*) FROM pg_proc fp JOIN pg_namespace n ON n.oid=fp.pronamespace WHERE n.nspname !~ '^pg_' AND n.nspname NOT IN('information_schema','extensions'))<>360 THEN RAISE EXCEPTION '58 unknown function catalog refused' USING ERRCODE='55000';END IF;
 IF EXISTS(SELECT 1 FROM pg_proc WHERE proname='validar_livro_recebimento') OR to_regnamespace('sucessores57') IS NOT NULL THEN RAISE EXCEPTION '58 one-shot/homonym/57 refused' USING ERRCODE='55000';END IF;
