CREATE FUNCTION obrigacoes51.validar_livro_recebimento(uid integer,aid integer,cid integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET TimeZone='UTC' AS $$
DECLARE a public.contas_caixa%ROWTYPE; t public.transacoes_caixa%ROWTYPE; oid37 uuid;
BEGIN
 IF uid IS NULL OR uid<=0 OR aid IS NULL OR aid<=0 OR cid IS NULL OR cid<=0 THEN RAISE EXCEPTION '58 alvo inválido' USING ERRCODE='22023';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.contas_caixa WHERE id=aid AND user_id=uid AND ativo IS TRUE)
 OR NOT EXISTS(SELECT 1 FROM public.contratos WHERE id=cid AND user_id=uid AND conta_caixa_id=aid) THEN RAISE EXCEPTION '58 alvo próprio ativo/vínculo necessário' USING ERRCODE='42501';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_locks WHERE locktype='advisory' AND pid=pg_backend_pid() AND granted AND classid=22022 AND objid=aid AND objsubid=2)
 OR NOT EXISTS(SELECT 1 FROM pg_locks WHERE locktype='advisory' AND pid=pg_backend_pid() AND granted AND classid=34034 AND objid=uid AND objsubid=2)
 OR NOT EXISTS(SELECT 1 FROM pg_locks WHERE locktype='advisory' AND pid=pg_backend_pid() AND granted AND classid=34035 AND objid=cid AND objsubid=2) THEN RAISE EXCEPTION '58 locks necessários' USING ERRCODE='42501';END IF;
 FOR a IN SELECT * FROM public.contas_caixa WHERE user_id=uid LOOP
 IF a.id<=0 OR a.saldo::text IN('NaN','Infinity','-Infinity') OR a.saldo<>round(a.saldo,2) OR abs(a.saldo)>9999999999999.99 THEN RAISE EXCEPTION 'Saldo-base37 inválido' USING ERRCODE='23514'; END IF;
 END LOOP;
 FOR t IN SELECT * FROM public.transacoes_caixa WHERE conta_caixa_id=aid OR contrato_id=cid OR parcela_id IN(SELECT id FROM public.parcelas WHERE contrato_id=cid) ORDER BY id LOOP
 IF t.id<=0 OR t.user_id IS DISTINCT FROM uid OR NOT EXISTS(SELECT 1 FROM public.contas_caixa WHERE id=t.conta_caixa_id AND user_id=uid)
 OR t.tipo IS NULL OR t.valor IS NULL OR t.data_transacao IS NULL OR t.tipo NOT IN('entrada','saida') OR t.valor::text IN('NaN','Infinity','-Infinity') OR t.valor<=0 OR t.valor<>round(t.valor,2) OR NOT isfinite(t.data_transacao)
 OR (t.contrato_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.contratos c JOIN public.clientes cl ON cl.id=c.cliente_id WHERE c.id=t.contrato_id AND c.user_id=uid AND cl.user_id=uid AND c.conta_caixa_id=t.conta_caixa_id AND (c.koletor_id IS NULL OR EXISTS(SELECT 1 FROM public.koletores WHERE id=c.koletor_id AND user_id=uid))))
 OR (t.parcela_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.parcelas p JOIN public.contratos c ON c.id=p.contrato_id JOIN public.clientes cl ON cl.id=p.cliente_id WHERE p.id=t.parcela_id AND p.user_id=uid AND c.user_id=uid AND cl.user_id=uid AND p.cliente_id=c.cliente_id AND p.contrato_id=t.contrato_id AND p.conta_caixa_id=t.conta_caixa_id AND (p.koletor_id IS NULL OR EXISTS(SELECT 1 FROM public.koletores WHERE id=p.koletor_id AND user_id=uid)))) THEN RAISE EXCEPTION 'Ledger37 whole-owner crossowner/estrutura inválida' USING ERRCODE='23514'; END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM public.caixa37_contas WHERE conta_id=aid AND user_id IS DISTINCT FROM uid) THEN RAISE EXCEPTION '58 pin alvo alheio' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT 1 FROM public.caixa37_operacoes o WHERE o.user_id IS DISTINCT FROM uid AND
 (o.request->'contaOrigemId'=to_jsonb(aid) OR o.request->'contaDestinoId'=to_jsonb(aid)
 OR o.id IN(SELECT primeira_op FROM public.caixa37_contas WHERE conta_id=aid)
 OR EXISTS(SELECT 1 FROM public.caixa37_pernas p LEFT JOIN public.transacoes_caixa l ON l.id=p.transacao_id WHERE p.operacao_id=o.id AND (l.conta_caixa_id=aid OR l.contrato_id=cid OR l.parcela_id IN(SELECT id FROM public.parcelas WHERE contrato_id=cid) OR p.snapshot->'conta_caixa_id'=to_jsonb(aid))))) THEN RAISE EXCEPTION '58 operação ligada alheia' USING ERRCODE='23514';END IF;
 FOR oid37 IN SELECT id FROM public.caixa37_operacoes WHERE user_id=uid LOOP PERFORM public.caixa37_validar_op(oid37); END LOOP;
 IF EXISTS(SELECT 1 FROM public.caixa37_contas p LEFT JOIN public.contas_caixa ac ON ac.id=p.conta_id WHERE p.user_id=uid AND (ac.id IS NULL OR ac.user_id IS DISTINCT FROM p.user_id OR ac.saldo IS DISTINCT FROM p.saldo_base)) THEN RAISE EXCEPTION 'Pin37 divergente' USING ERRCODE='23514'; END IF;
END $$;
REVOKE ALL ON FUNCTION obrigacoes51.validar_livro_recebimento(integer,integer,integer) FROM PUBLIC,anon,authenticated,service_role;

DO $helper_exact58$ DECLARE p pg_proc%ROWTYPE;a jsonb;BEGIN
 SELECT * INTO STRICT p FROM pg_proc WHERE oid='obrigacoes51.validar_livro_recebimento(integer,integer,integer)'::regprocedure;
 a:=(to_jsonb(p)-ARRAY['oid','pronamespace','proowner','prolang','proargtypes','prorettype','prosrc'])||jsonb_build_object('schema',(SELECT nspname FROM pg_namespace WHERE oid=p.pronamespace),'owner',pg_get_userbyid(p.proowner),'language',(SELECT lanname FROM pg_language WHERE oid=p.prolang),'argument_types',(SELECT jsonb_agg(format_type(t,NULL) ORDER BY ord) FROM unnest(p.proargtypes::oid[]) WITH ORDINALITY a(t,ord)),'return_type',format_type(p.prorettype,NULL),'body_sha256',encode(extensions.digest(p.prosrc,'sha256'),'hex'));
 IF a IS DISTINCT FROM '{"proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","proname":"validar_livro_recebimento","prorows":0,"pronargs":3,"proconfig":["search_path=pg_catalog, pg_temp","TimeZone=UTC"],"proretset":false,"prosecdef":true,"prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["uid","aid","cid"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0,"schema":"obrigacoes51","owner":"postgres","language":"plpgsql","argument_types":["integer","integer","integer"],"return_type":"void","body_sha256":"41038ea0b537f300abd227598bc4aade092e35de40b6e79a8fea26441c906e76"}'::jsonb THEN RAISE EXCEPTION '58 helper exact metadata/body/config/ACL mismatch' USING ERRCODE='55000';END IF;
END $helper_exact58$;
CREATE TEMP TABLE witness58_helper ON COMMIT DROP AS SELECT oid,to_jsonb(p) snapshot FROM pg_proc p WHERE oid='obrigacoes51.validar_livro_recebimento(integer,integer,integer)'::regprocedure;

DO $plan58$ DECLARE q text;b text;s text;BEGIN
 IF (SELECT encode(extensions.digest(prosrc,'sha256'),'hex') FROM pg_proc WHERE oid='obrigacoes51.metadata()'::regprocedure) IS DISTINCT FROM '5d876307e7b81bb6e1e19d22dde48de5afc2243802be4a6f68e69ade289ae662' THEN RAISE EXCEPTION '58 metadata original drift' USING ERRCODE='55000';END IF;
 IF (SELECT encode(extensions.digest(prosrc,'sha256'),'hex') FROM pg_proc WHERE oid='obrigacoes51.validar_livro_recebimento(integer,integer,integer)'::regprocedure) IS DISTINCT FROM '41038ea0b537f300abd227598bc4aade092e35de40b6e79a8fea26441c906e76' THEN RAISE EXCEPTION '58 helper static body drift' USING ERRCODE='55000';END IF;
 IF (SELECT proconfig::text FROM pg_proc WHERE oid='obrigacoes51.validar_livro_recebimento(integer,integer,integer)'::regprocedure) IS DISTINCT FROM '{"search_path=pg_catalog, pg_temp",TimeZone=UTC}' OR NOT (SELECT prosecdef FROM pg_proc WHERE oid='obrigacoes51.validar_livro_recebimento(integer,integer,integer)'::regprocedure) THEN RAISE EXCEPTION '58 helper config drift' USING ERRCODE='55000';END IF;
 IF has_function_privilege('anon','obrigacoes51.validar_livro_recebimento(integer,integer,integer)','EXECUTE') OR has_function_privilege('authenticated','obrigacoes51.validar_livro_recebimento(integer,integer,integer)','EXECUTE') OR has_function_privilege('service_role','obrigacoes51.validar_livro_recebimento(integer,integer,integer)','EXECUTE') OR (SELECT proacl::text FROM pg_proc WHERE oid='obrigacoes51.validar_livro_recebimento(integer,integer,integer)'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres}' THEN RAISE EXCEPTION '58 helper ACL not closed' USING ERRCODE='55000';END IF;
 SELECT expression,candidate_body INTO q,b FROM plan58;EXECUTE q INTO s USING b;UPDATE plan58 SET expected_signature=s;
END $plan58$;
CREATE OR REPLACE FUNCTION obrigacoes51.cotacao(uid integer,cid integer,v jsonb,instante timestamptz) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET TimeZone='UTC' AS $$
DECLARE b jsonb;s jsonb;plan jsonb;q jsonb;p jsonb;source text;a text;pid integer;ids integer[]:='{}';due numeric:=0;val numeric;total numeric;additional numeric;day date:=(instante AT TIME ZONE 'America/Sao_Paulo')::date;dest integer;anycancel boolean;
BEGIN
 PERFORM obrigacoes51.verificar();v:=obrigacoes51.proposta(v);PERFORM obrigacoes51.travar(uid,cid);b:=obrigacoes51.base(uid,cid);s:=b->'financeiro';source:=b->>'origemTipo';a:=v->>'acao';total:=(s->'contrato'->>'total_contrato')::numeric;plan:=jsonb_build_object('totalContrato',total::numeric(12,2)::text);
 IF jsonb_array_length(s->'parcelas') NOT BETWEEN 1 AND 60 THEN RAISE EXCEPTION '51 conjunto1..60 íntegro necessário' USING ERRCODE='54000';END IF;
 anycancel:=b->'encerramento' IS DISTINCT FROM 'null'::jsonb OR jsonb_array_length(b->'cancelamentos')>0;
 IF a IN('adicionar','editar') AND anycancel THEN RAISE EXCEPTION '51 conjunto renunciado não pode ser reprecificado/adicionado' USING ERRCODE='23514';END IF;
 IF a='adicionar' THEN PERFORM inclusao52.verificar();
 IF source='multimodal35' AND s->'contrato'->>'modalidade'='mensal' THEN
 IF EXISTS(SELECT 1 FROM obrigacoes51.arquivos WHERE contrato_id=cid LIMIT 1) THEN RAISE EXCEPTION '52 append não reabre arquivo' USING ERRCODE='23514';END IF;
 s:=obrigacoes51.validar_mensal(uid,cid);PERFORM private47.estado_auditado(uid,cid,s);plan:=obrigacoes51.plano(s,v,instante);
 ELSE s:=inclusao52.validar(uid,cid,s,source);plan:=inclusao52.plano(s,v,instante);END IF;ids:='{}'::integer[];
 ELSIF a='editar' THEN
 IF source NOT IN('multimodal35','prospectivo21') THEN RAISE EXCEPTION '51 edição requer origem35/21 comprovada, não legado presumido' USING ERRCODE='0A000';END IF;
 IF source='multimodal35' THEN s:=obrigacoes51.validar_mensal(uid,cid);ELSE
 IF NOT EXISTS(SELECT 1 FROM public.ciclo_estados WHERE contrato_id=cid AND user_id=uid AND origem_completa LIMIT 1) THEN RAISE EXCEPTION '51 edição21 requer estado completo genuíno' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT 1 FROM public.renovacao_operacoes WHERE contrato_id=cid LIMIT 1) OR EXISTS(SELECT 1 FROM public.multa36_origens WHERE contrato_id=cid LIMIT 1) THEN RAISE EXCEPTION '51 edição21 não renovada/multa' USING ERRCODE='0A000';END IF;END IF;
 plan:=obrigacoes51.plano(s,v,instante);pid:=obrigacoes51.id(v->'parcelaId');ids:=ARRAY[pid];
 ELSIF a IN('cancelar','arquivar') THEN
 IF s->'contrato'->>'status' IN('renegociado') OR EXISTS(SELECT 1 FROM public.contratos WHERE contrato_origem_id=cid LIMIT 1) THEN RAISE EXCEPTION '51 obrigação transferida: atuar no sucessor exigível' USING ERRCODE='0A000';END IF;
 IF v->'alvo'->>'tipo'='parcela' THEN pid:=obrigacoes51.id(v->'alvo'->'parcelaId');IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s->'parcelas') j WHERE (j->>'id')::int=pid) THEN RAISE EXCEPTION '51 alvo indisponível' USING ERRCODE='42501';END IF;END IF;
 FOR p IN SELECT value FROM jsonb_array_elements(s->'parcelas') ORDER BY (value->>'id')::int LOOP
 IF pid IS NULL OR (p->>'id')::int=pid THEN
 val:=obrigacoes51.registrada(p);IF anycancel AND (b->'encerramento' IS DISTINCT FROM 'null'::jsonb OR EXISTS(SELECT 1 FROM obrigacoes51.cancelamentos WHERE parcela_id=(p->>'id')::int LIMIT 1)) THEN val:=0;END IF;
 IF a='cancelar' AND val>0 THEN ids:=array_append(ids,(p->>'id')::int);due:=due+val;
 ELSIF a='arquivar' THEN IF val>0 THEN RAISE EXCEPTION '51 somente histórico encerrado pode ser arquivado' USING ERRCODE='23514';END IF;ids:=array_append(ids,(p->>'id')::int);END IF;
 END IF;END LOOP;
 IF a='arquivar' AND EXISTS(SELECT 1 FROM obrigacoes51.arquivos WHERE contrato_id=cid AND parcela_id IS NOT DISTINCT FROM pid LIMIT 1) THEN RAISE EXCEPTION '51 histórico já arquivado' USING ERRCODE='22023';END IF;
 ELSIF a='quitar' THEN
 dest:=obrigacoes51.id(v->'contaCaixaId');
 IF dest IS DISTINCT FROM (s->'contrato'->>'conta_caixa_id')::int THEN RAISE EXCEPTION '51 escolha explícita deve corresponder à conta vinculada neste recorte; jamais default silencioso' USING ERRCODE='0A000';END IF;
 PERFORM obrigacoes51.validar_livro_recebimento(uid,dest,cid);
 IF NOT EXISTS(SELECT 1 FROM public.contas_caixa WHERE id=dest AND user_id=uid AND ativo LIMIT 1) THEN RAISE EXCEPTION '51 conta destino própria ativa obrigatória' USING ERRCODE='42501';END IF;
 FOR p IN SELECT value FROM jsonb_array_elements(s->'parcelas') ORDER BY (value->>'id')::int LOOP
 IF obrigacoes51.registrada(p)>0 AND NOT EXISTS(SELECT 1 FROM obrigacoes51.cancelamentos WHERE parcela_id=(p->>'id')::int LIMIT 1) AND b->'encerramento'='null'::jsonb THEN
 IF source='multimodal35' THEN q:=public.multimodal_cotacao(uid,cid,(p->>'id')::int,instante);
 ELSIF source='prospectivo21' THEN q:=public.ciclo_cotacao(uid,cid,(p->>'id')::int);
 ELSE q:=public.legados_validar(uid,cid,(p->>'id')::int,dest);END IF;
 IF q->'elegivel' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION '51 título não elegível à baixa real' USING ERRCODE='23514';END IF;
 due:=due+(q->>'totalExigido')::numeric;ids:=array_append(ids,(p->>'id')::int);
 END IF;END LOOP;
 IF due IS DISTINCT FROM obrigacoes51.dinheiro(v->>'valorRecebido') THEN RAISE EXCEPTION '51 dinheiro real informado deve igualar exigibilidade cotada; sem quitação presumida/desconto implícito' USING ERRCODE='22023';END IF;
 END IF;
 IF (cardinality(ids)=0 AND a<>'adicionar') OR NOT public.multimodal_moeda(due) THEN RAISE EXCEPTION '51 sem obrigação/alvo/delta ou valor fora faixa' USING ERRCODE='22023';END IF;
 SELECT coalesce(sum(valor),0) INTO additional FROM (SELECT valor FROM obrigacoes51.adicionais WHERE contrato_id=cid UNION ALL SELECT valor FROM inclusao52.adicionais WHERE contrato_id=cid) extras;
 RETURN jsonb_build_object('versao','obrigacoes51_v1','userId',uid,'contratoId',cid,'proposta',v,'origem',source,'estadoHash',obrigacoes51.hash(jsonb_build_object('base',b,'dia',day)),'dataCalculo',day,'totalAntes',total::numeric(12,2)::text,'totalDepois',plan->>'totalContrato','obrigacaoAdicional',(additional+CASE WHEN a='adicionar' THEN (v->>'valor')::numeric ELSE 0 END)::numeric(12,2)::text,'valorExigido',CASE WHEN a='quitar' THEN due::numeric(12,2)::text ELSE '0.00' END,'contaDestinoId',dest,'idsAfetados',ids,'caixaPreservado',a<>'quitar');
END $$;

DO $post58$ DECLARE w record;p jsonb;r record;j jsonb;BEGIN
 FOR w IN SELECT * FROM witness58_functions LOOP SELECT to_jsonb(x) INTO p FROM pg_proc x WHERE oid=w.oid; IF w.name='obrigacoes51.cotacao' THEN IF p-'prosrc' IS DISTINCT FROM w.snapshot-'prosrc' OR encode(extensions.digest(p->>'prosrc','sha256'),'hex') IS DISTINCT FROM '6a154287234e987c2392ee1d53cc5fcb815df6011063837c0a89642f611919a9' THEN RAISE EXCEPTION '58 cotacao delta not exact' USING ERRCODE='55000';END IF;ELSE IF p IS DISTINCT FROM w.snapshot THEN RAISE EXCEPTION '58 original function changed %',w.name USING ERRCODE='55000';END IF;END IF;END LOOP;
 IF (SELECT count(*) FROM pg_proc fp JOIN pg_namespace n ON n.oid=fp.pronamespace WHERE n.nspname !~ '^pg_' AND n.nspname NOT IN('information_schema','extensions'))<>(SELECT count(*)+1 FROM witness58_functions) THEN RAISE EXCEPTION '58 unexpected added functions' USING ERRCODE='55000';END IF;
 IF obrigacoes51.metadata() IS DISTINCT FROM (SELECT expected_signature FROM plan58) THEN RAISE EXCEPTION '58 expected metadata signature mismatch' USING ERRCODE='55000';END IF;
 UPDATE obrigacoes51.manifesto SET assinatura=(SELECT expected_signature FROM plan58) WHERE id=1;
 FOR r IN SELECT * FROM witness58_data LOOP EXECUTE 'SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),''[]''::jsonb) FROM '||r.relation||' x' INTO j;
 IF r.relation='obrigacoes51.manifesto' THEN IF j IS DISTINCT FROM jsonb_build_array(jsonb_set(r.snapshot->0,'{assinatura}',to_jsonb((SELECT expected_signature FROM plan58)))) THEN RAISE EXCEPTION '58 unexpected manifesto51 delta' USING ERRCODE='55000';END IF;
 ELSE IF j IS DISTINCT FROM r.snapshot THEN RAISE EXCEPTION '58 unexpected physical/signature DML %',r.relation USING ERRCODE='55000';END IF;END IF;END LOOP;
END $post58$;
